<?php
require_once __DIR__.'/includes/bootstrap.php';requireLogin();$pdo=db();$s=$pdo->prepare('SELECT * FROM users WHERE id=?');$s->execute([currentUserId()]);$u=$s->fetch();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$username=trim((string)($_POST['username']??''));$email=strtolower(trim((string)($_POST['email']??'')));$cur=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');if(!preg_match('/^[A-Za-z0-9_]{3,50}$/',$username))$errors[]='Invalid username.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Invalid email.';$s=$pdo->prepare('SELECT id FROM users WHERE (username=? OR email=?) AND id<>? LIMIT 1');$s->execute([$username,$email,currentUserId()]);if($s->fetch())$errors[]='Username or email already exists.';if($new!==''){if(!password_verify($cur,$u['password_hash']))$errors[]='Current password is incorrect.';if(strlen($new)<10)$errors[]='New password must be at least 10 characters.';}if(!$errors){if($new!==''){$s=$pdo->prepare('UPDATE users SET username=?,email=?,password_hash=? WHERE id=?');$s->execute([$username,$email,password_hash($new,PASSWORD_DEFAULT),currentUserId()]);}else{$s=$pdo->prepare('UPDATE users SET username=?,email=? WHERE id=?');$s->execute([$username,$email,currentUserId()]);}$_SESSION['username']=$username;$_SESSION['email']=$email;flash('success','Profile updated.');redirect('profile.php');}}
$pageTitle='Profile';include __DIR__.'/includes/header.php';
?>
<div class="card narrow-card"><h1>Profile</h1><?php foreach($errors as $e1): ?><div class="alert error"><?= e($e1) ?></div><?php endforeach; ?><form method="post"><?= csrf_field() ?><label>Username<input name="username" value="<?= e($u['username']) ?>" required></label><label>Email<input type="email" name="email" value="<?= e($u['email']) ?>" required></label><hr><h2>Change Password</h2><label>Current Password<input type="password" name="current_password"></label><label>New Password<input type="password" name="new_password"></label><button type="submit" class="btn primary">Save Changes</button></form></div>
<?php include __DIR__.'/includes/footer.php'; ?>
